Solution B: function generateAndSolveMaze(canvasId){
    const generationDelay=20, solvingDelay=20;
    const rows=25, cols=25, cellSize=20;
    const canvas=document.getElementById(canvasId);
    if(!canvas||!canvas.getContext) throw new Error('Canvas not found or unsupported');
    canvas.width=canvas.height=500;
    const ctx=canvas.getContext('2d');
    const grid=Array.from({length:rows},()=>Array.from({length:cols},()=>({top:true,bottom:true,left:true,right:true})));
    function drawCell(x,y){
        const cx=x*cellSize, cy=y*cellSize;
        ctx.strokeStyle='black';
        ctx.lineWidth=2;
        ctx.beginPath();
        if(grid[y][x].top) ctx.moveTo(cx,cy),ctx.lineTo(cx+cellSize,cy);
        if(grid[y][x].right) ctx.moveTo(cx+cellSize,cy),ctx.lineTo(cx+cellSize,cy+cellSize);
        if(grid[y][x].bottom) ctx.moveTo(cx+cellSize,cy+cellSize),ctx.lineTo(cx,cy+cellSize);
        if(grid[y][x].left) ctx.moveTo(cx,cy+cellSize),ctx.lineTo(cx,cy);
        ctx.stroke();
    }
    function clearCanvas(){ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);}
    function drawAll(){clearCanvas();for(let y=0;y<rows;y++)for(let x=0;x<cols;x++)drawCell(x,y);}
    function sleep(ms){return new Promise(r=>setTimeout(r,ms));}
    function recursiveDivision(x,y,w,h,orient){
        if(w<2||h<2) return;
        const horizontal = orient==='horizontal';
        const wx = x + (horizontal?0:Math.floor(Math.random()*(w-1)));
        const wy = y + (horizontal?Math.floor(Math.random()*(h-1)):0);
        const passage = horizontal?
            (x + Math.floor(Math.random()*w)):
            (y + Math.floor(Math.random()*h));
        const length = horizontal?h:w;
        for(let i=0;i<length;i++){
            if(horizontal){
                if(y+i===passage) continue;
                const cx=wx, cy=y+i;
                if(cx>0){
                    grid[cy][cx-1].right=true;
                    grid[cy][cx].left=true;
                }
            }else{
                if(x+i===passage) continue;
                const cx=x+i, cy=;
                if(cy>0){
                    grid[cy-1][cx].bottom=true;
                    grid[cy][cx].top=true;
                }
            }
        }
        drawAll();
        sleep(generationDelay);
        const w1=horizontal?w:h, h1=horizontal?h:w;
        if(horizontal){
            recursiveDivision(x,y,w,wy-y,'vertical');
            recursiveDivision(x,wy+1,w,h-(wy-y+1),'vertical');
        }else{
            recursiveDivision(x,y,wx-x,h,'horizontal');
            recursiveDivision(wx+1,y,w-(wx-x+1),h,'');
        }
    }
    async function generate(){
        for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){
            if(y===0) grid[y][x].top=true;
            if(y===rows-1) grid[y][x].bottom=true;
            if(x===0) grid[y][x].left=true;
            if(x===cols-1) grid[y][x].right=true;
        }
        drawAll();
        await sleep(generationDelay);
        const orient=cols>rows?'vertical':'horizontal';
        await recursiveDivision(0,0,cols,rows,orient);
    }
    async function solve(){
        const start={x:0,y:0}, goal={x:cols-1,y:rows-1};
        const open=[], closed=[];
        function nodeKey(p){return p.x+','+p.y;}
        function heuristic(a,b){return Math.abs(a.x-b.x)+Math.abs(a.y-b.y);}
        open.push({x:start.x,y:start.y,g:0,f:heuristic(start,goal),parent:null});
        const cameFrom={};
        while(open.length){
            open.sort((a,b)=>a.f-b.f);
            const current=open.shift();
            if(current.x===goal.x && current.y===goal.y){
                let cur=current;
                ctx.fillStyle='lime';
                while(cur){
                    ctx.fillRect(cur.x*cellSize+4,cur.y*cellSize+4,cellSize-8,cellSize-8);
                    cur=cur.parent;
                }
                return;
            }
            closed.push(nodeKey(current));
            const neighbors=[];
            if(!grid[current.y][current.x].top) neighbors.push({x:current.x,y:current.y-1});
            if(!grid[current.y][current.x].bottom) neighbors.push({x:current.x,y:current.y+1});
            if(!grid[current.y][current.x].left) neighbors.push({x:current.x-1,y:current.y});
            if(!grid[current.y][current.x].right) neighbors.push({x:current.x+1,y:current.y});
            for(const nb of neighbors){
                if(closed.includes(nodeKey(nb))) continue;
                const tentativeG=current.g+1;
                let openNode=open.find(n=>n.x===nb.x&&n.y===nb.y);
                if(!openNode){
                    openNode={x:nb.x,y:nb.y,g:tentativeG,f:tentativeG+heuristic(nb,goal),parent:current};
                    open.push(openNode);
                }else if(tentativeG<openNode.g){
                    openNode.g=tentativeG;
                    openNode.f=tentativeG+heuristic(nb,goal);
                    openNode.parent=current;
                }
            }
            ctx.fillStyle='rgba(0,0,255,0.3)';
            ctx.fillRect(current.x*cellSize+2,current.y*cellSize+2,cellSize-4,cellSize-4);
            await sleep(solvingDelay);
        }
 }
    (async()=>{await generate();await solve();})();
}

